var CMS_DEFAULT = "resume-templates";
function buildBreadcrumbs(slug, title, pages) {
  var root = "https://www.naukri.com";
  var base = root + "/naukri360";
  var crumbs = [
    {n:"Home", u:root},
    {n:"Naukri360", u:base}
  ];
  var parts = String(slug||"").split("/").filter(Boolean);
  var path = "";
  for (var i = 0; i < parts.length; i++) {
    path = path ? path + "/" + parts[i] : parts[i];
    var isLast = (i === parts.length - 1);
    var name;
    if (isLast) {
      name = title;
    } else if (pages && pages[path] && pages[path].title) {
      name = pages[path].title;
    } else {
      name = parts[i].replace(/-/g," ").replace(/\b\w/g,function(c){return c.toUpperCase()});
    }
    crumbs.push({n:name, u:base + "/" + path});
  }
  return crumbs;
}
function clonePage(src, slug, title) {
  var c = JSON.parse(JSON.stringify(CMS_PAGES[src]));
  c.slug = slug; c.title = title; c.created = new Date().toISOString().slice(0,10);
  c.seo.title = title + " | Naukri360";
  c.seo.canonical = "https://www.naukri.com/naukri360/" + slug;
  c.hero.h1 = "Free " + title + " Resume Templates";
  c.hero.text = "Create a professional " + title.toLowerCase() + " resume in minutes.";
  var parentSlug = slug.indexOf("/") > -1 ? slug.substring(0, slug.lastIndexOf("/")) : "";
  c.parent = parentSlug;
  c.schema.breadcrumbs = buildBreadcrumbs(slug, title, CMS_PAGES);
  CMS_PAGES[slug] = c;
  return c;
}
